TREES = {
    "oak": ("Europa bis zum Kaukasus", "Ein breiter, langlebiger Baum mit gelappten Blättern und Eicheln. Eine einzige Eiche beherbergt Hunderte Insektenarten, und ihr Holz baute tausend Jahre lang Europas Schiffe und Kathedralen."),
    "birch": ("Europa und Nordasien", "Eine schlanke Pionierin mit weißer Rinde, die sich in papierdünnen Streifen ablöst. Birkenrinde ist wasserdicht und brennt selbst feucht; man machte daraus Kanus, Schachteln und die ersten Briefe von Nowgorod."),
    "spruce": ("Nord- und Mitteleuropa", "Ein hoher, kegelförmiger Nadelbaum mit kurzen, vierkantigen Nadeln und hängenden Zapfen. Sein leichtes, gleichmäßiges Holz liefert die Resonanzböden von Geigen und Klavieren; er ist der klassische Weihnachtsbaum."),
    "jungle": ("", "Ein Baum nur dieser Welt: ein riesiger Regenwaldstamm voller Lianen und Kakaofrüchte. Echte Regenwälder tragen stattdessen Hunderte Baumarten auf einem einzigen Hektar."),
    "acacia": ("Afrika und die Arabische Halbinsel", "Die Schirmakazie: eine flache Krone aus winzigen Blättchen auf einem gegabelten Stamm, bewehrt mit langen Dornen. Giraffen greifen mit halbmeterlangen Zungen an den Dornen vorbei."),
    "dark_oak": ("", "Ein Baum nur dieser Welt: eine dicke, vierstämmige Eiche, die den Waldboden so tief beschattet, dass darunter riesige Pilze wachsen."),
    "mangrove": ("Tropische Küsten des Atlantiks und des Ostpazifiks", "Die Rote Mangrove steht auf gebogenen Stelzwurzeln im Salzwasser. Ihre Samen keimen noch am Baum und fallen als Speere herab, die monatelang treiben, bevor sie wurzeln."),
    "cherry": ("Japan, Korea und China", "Die Japanische Blütenkirsche: gezogen wegen ihrer rosa Blütenwolken, nicht wegen der Früchte. Ihre kurze Blüte jeden Frühling wird in Japan als Hanami gefeiert."),
    "azalea": ("Gebirge Asiens, Europas und Nordamerikas", "Azaleen sind strauchige Rhododendren mit trichterförmigen Blüten. Der Honig mancher Arten ist giftig; in dieser Welt zeigen sie die üppigen Höhlen darunter an."),
    "mahogany": ("Mexiko bis zum südlichen Amazonas", "Großblättriges Mahagoni: ein gerader Riese mit rötlichem, formstabilem Holz. Jahrhunderte des Holzeinschlags für edle Möbel machten es selten, heute regelt ein Abkommen seinen Handel."),
    "brazil_nut": ("Amazonas-Regenwald", "Einer der höchsten Bäume Amazoniens. Seine Nüsse wachsen in einer harten Kugel von der Größe einer Kokosnuss, die nur das Aguti aufnagen kann; das Aguti vergräbt übrige Nüsse und pflanzt so neue Bäume."),
    "brazilwood": ("Atlantischer Regenwald Brasiliens", "Ein dorniger Baum mit orangerotem Kernholz, der Brasilien seinen Namen gab. Sein roter Farbstoff ging ab 1501 nach Europa; heute macht sein Holz die besten Geigenbögen."),
    "sapodilla": ("Südmexiko und Mittelamerika", "Ein immergrüner Baum mit süßen braunen Früchten, die nach Birne und Malz schmecken. Sein milchiger Saft, Chicle, war der ursprüngliche Kaugummi."),
    "andiroba": ("Amazonasbecken und Karibik", "Ein Verwandter des Mahagonis aus dem Regenwald mit großen holzigen Früchten. Das bittere Öl aus seinen Samen hilft gegen Insektenstiche und dient als Lampenöl."),
    "acai": ("Amazonasmündung", "Eine schlanke Palme, die in Büscheln an überfluteten Ufern wächst. Ihre violetten Beeren sind an der Amazonasmündung ein Grundnahrungsmittel, ihr Herz wird als Palmherz gegessen."),
    "babassu": ("Ostamazonien und Nordostbrasilien", "Eine hohe Palme mit riesigen aufrechten Wedeln. Ihre harten Nüsse enthalten ein Öl ähnlich dem Kokosöl; in Maranhão knacken Frauen sie von Hand mit Axt und Knüppel."),
    "copaiba": ("Brasilien, Paraguay und Bolivien", "Ein Baum, dessen Stamm ein öliges Harz enthält, das aus einem gebohrten Loch fließt. Copaivabalsam wurde ab dem 17. Jahrhundert in europäischen Apotheken verkauft."),
    "cinchona": ("Anden in Ecuador und Peru", "Ein kleiner Andenbaum, dessen bittere Rinde Chinin enthält, das erste Heilmittel gegen Malaria. Er steht im Wappen Perus."),
    "oil_palm": ("West- und Zentralafrika", "Eine Fiederpalme, deren orange Fruchtstände Palmöl liefern, das meistproduzierte Pflanzenöl der Erde. Ein Fruchtstand kann 40 Kilogramm wiegen."),
    "teak": ("Indien, Myanmar, Laos und Thailand", "Ein hoher, laubwerfender Baum mit Blättern so groß wie ein Teller. Sein öliges goldenes Holz widersteht Wasser und Termiten und war daher das Holz der Schiffsdecks."),
    "cinnamon": ("Sri Lanka und Südindien", "Ein immergrüner Lorbeer, dessen Innenrinde, geschält und getrocknet, sich zu Zimtstangen rollt. Sein Duft stammt vom Zimtaldehyd."),
    "camphor_laurel": ("China, Japan und Korea", "Ein breiter immergrüner Baum, dessen zerriebene Blätter nach Kampfer riechen. Aus seinem Holz destillierter Kampfer ergab Zelluloid, den ersten Kunststofffilm."),
    "sal": ("Himalaya-Vorgebirge in Indien und Nepal", "Ein hoher, fast immergrüner Baum, der ganze Wälder bildet. Sein hartes Holz trägt indische Häuser, sein Harz wird als Weihrauch verbrannt; Buddha soll unter einem geboren sein."),
    "nutmeg": ("Bandainseln, Indonesien", "Ein immergrüner Baum, dessen Samen die Muskatnuss und dessen roter Samenmantel die Muskatblüte ist. Um die winzigen Bandainseln, wo allein er wuchs, wurden Kriege geführt."),
    "baobab": ("Tropisches Afrika", "Ein riesiger flaschenförmiger Stamm, der Wasser für die Trockenzeit speichert. Baobabs können über 2.000 Jahre alt werden; ihr trockenes Fruchtmark ist reich an Vitamin C."),
    "gum_arabic_tree": ("Sahel und Sudan", "Ein kleiner dorniger Baum des Sahel. Sein Saft erhärtet zu Gummi arabicum, das in Limonaden, Briefmarken, Aquarellfarben und Druckfarben steckt."),
    "marula": ("Südliches und Ostafrika", "Ein Savannenbaum mit pflaumengroßen gelben Früchten, die Elefanten lieben. Aus der Frucht macht man Bier und Likör, die Nüsse geben ein haltbares Öl."),
    "shea": ("Savanne West- und Zentralafrikas", "Ein langsam wachsender Baum, der erst nach 15 Jahren Früchte trägt. Seine Nüsse liefern Sheabutter, ein Fett für Speisen, Seife und Schokolade."),
    "eucalyptus": ("Tasmanien und Südostaustralien", "Der Tasmanische Blaugummibaum: ein schnellwüchsiger Riese mit abblätternder Rinde und blauen Jugendblättern. Sein Öl, Eukalyptol, macht die Nase frei; seine Plantagen beliefern Papierfabriken weltweit."),
    "pequi": ("Cerrado Brasiliens", "Ein knorriger Cerrado-Baum mit gelber, stark duftender Frucht. Unter dem Fruchtfleisch verbirgt der Kern feine Stacheln, daher wird die Frucht abgenagt, nie gebissen."),
    "barbatimao": ("Cerrado Brasiliens", "Ein kleiner Cerrado-Baum mit dicker, korkiger Rinde. Die Rinde ist so gerbstoffreich, dass man mit ihr Leder gerbte und Wunden behandelte."),
    "yellow_ipe": ("Tropisches Südamerika", "In der Trockenzeit wirft er alle Blätter ab und blüht leuchtend gelb. Sein Holz, Ipe, gehört zu den härtesten und dichtesten der Welt."),
    "jatoba": ("Mittel- und Südamerika", "Ein großer Baum mit paarigen Blättchen und Hülsen voller süßem, mehligem Mark. Sein Harz, Kopal, wurde über Jahrmillionen zu Bernstein."),
    "sandalwood": ("Indien, Indonesien und Nordaustralien", "Ein Halbschmarotzer, dessen Wurzeln Wasser aus den Wurzeln anderer Pflanzen ziehen. Sein duftendes Kernholz und Öl sind so wertvoll, dass wilde Bäume fast ganz abgeholzt wurden."),
    "dragon_tree": ("Insel Sokotra, Jemen", "Ein Schirm aus steifen Blättern auf dicken Ästen, der nur auf Sokotra wächst. Sein rotes Harz, Drachenblut, war in der Antike Farbstoff und Firnis."),
    "frankincense": ("Oman, Jemen und Somalia", "Ein kleiner Baum, der auf nacktem Fels wächst. Schnitte in seine papierne Rinde lassen ein milchiges Harz austreten, das zu Weihrauch trocknet, seit 5.000 Jahren über Arabien gehandelt."),
    "myrrh": ("Horn von Afrika und Südarabien", "Ein dorniger, strauchiger Baum trockener, steiniger Böden. Sein rötliches Harz, Myrrhe, diente im alten Ägypten für Parfüm, Medizin und Einbalsamierung."),
    "date_palm": ("Naher Osten und Nordafrika", "Die Nutzpalme der Wüste, seit mindestens 7.000 Jahren in Oasen angebaut. Weibliche Bäume tragen Fruchtstände mit bis zu tausend Datteln."),
    "mesquite": ("Mexiko, Mittelamerika und Karibik", "Ein dorniger Baum, dessen Wurzeln Wasser in 50 Metern Tiefe erreichen. Seine süßen Hülsen füttern Vieh und wurden von Wüstenvölkern zu Mehl gemahlen."),
    "joshua_tree": ("Mojave-Wüste", "Eine Riesen-Yucca mit stacheligen, verzweigten Armen, kein echter Baum. Nur eine einzige Motte bestäubt ihre Blüten, und deren Raupen fressen nur ihre Samen."),
    "saxaul": ("Wüsten Zentralasiens", "Ein blattloser Wüstenbaum mit grünen Zweigen statt Blättern. Sein Holz ist so dicht, dass es im Wasser sinkt und wie Kohle brennt."),
    "argan": ("Südwestmarokko", "Ein dorniger, dürrefester Baum, auf den Ziegen klettern, um die Früchte zu fressen. Seine Kerne liefern Arganöl für Küche und Kosmetik."),
    "palo_verde": ("Sonora-Wüste", "Der Name bedeutet grüner Stock: Die Rinde ist grün und übernimmt den Großteil der Photosynthese, wenn die winzigen Blätter in der Dürre fallen. Im Frühling wird er leuchtend gelb vor Blüten."),
    "pinyon_pine": ("Colorado-Plateau und Südwesten der USA", "Eine kleine, langsame Kiefer trockener Hügel. Ihre großen Nüsse waren eine Hauptnahrung der Völker des Großen Beckens und werden noch jeden Herbst gesammelt."),
    "utah_juniper": ("Großes Becken und Colorado-Plateau", "Ein knorriger Wacholder trockener Hänge, der 650 Jahre alt werden kann. Seine blauen Beeren sind in Wahrheit fleischige Zapfen, die Vögel fressen."),
    "desert_ironwood": ("Sonora-Wüste", "Eines der schwersten Hölzer der Welt: Es sinkt im Wasser. Viele Wüstenpflanzen beginnen ihr Leben in seinem Schatten, darum heißt er Ammenbaum."),
    "tamarisk": ("Nordafrika bis Indien", "Eine Salzzeder mit winzigen Schuppenblättern, die Salz ausschwitzen. Sie wächst dort, wo das Grundwasser für andere Bäume zu salzig ist."),
    "ponderosa_pine": ("Westliches Nordamerika", "Eine hohe Kiefer mit oranger, geplatteter Rinde, die an warmen Tagen nach Vanille duftet. Dank der dicken Rinde übersteht sie die Bodenfeuer, die durch ihre Wälder ziehen."),
    "gambel_oak": ("Südwesten der USA und Rocky Mountains", "Eine strauchige Eiche, die sich über Wurzeln zu Dickichten ausbreitet. Ihre Eicheln ernährten Hirsche, Truthühner und die Völker der Region."),
    "mountain_mahogany": ("Gebirge des westlichen Nordamerika", "Kein Mahagoni, sondern ein Rosengewächs. Seine Samen tragen einen fedrigen Schweif, der sich mit der Feuchtigkeit dreht und den Samen in den Boden bohrt."),
    "elephant_tree": ("Sonora-Wüste und Baja California", "Ein gedrungener Baum mit geschwollenem, wasserspeicherndem Stamm und papierartig abblätternder Rinde. Seine Zweige riechen nach Terpentin und geben ein Kopalharz."),
    "coconut_palm": ("Tropische Küsten des Indischen und Pazifischen Ozeans", "Die Palme tropischer Strände. Ihre Nuss schwimmt und bleibt monatelang auf See lebendig, so verbreitete sie sich über die Ozeane."),
    "tropical_almond": ("Tropisches Asien, Australien und Pazifik", "Ein Strandbaum mit etagenartigen Ästen und großen Blättern, die sich vor dem Fallen rot färben. Seine Samen schmecken nach Mandel, und gefallene Blätter färben Wasser mit Gerbstoff braun."),
    "casuarina": ("Südostasien, Australien und Pazifik", "Sie sieht aus wie eine Kiefer, ist aber ein Blütenbaum mit gegliederten grünen Zweigen. Ihre Wurzeln binden Stickstoff, so wächst sie auf nacktem Sand."),
    "screw_pine": ("Küsten des Pazifiks und des Indischen Ozeans", "Die Blätter winden sich wie eine Schraube um den Stamm, und Stelzwurzeln halten ihn aufrecht im Sand. Aus den Blättern flicht man Matten und Dächer."),
    "sea_grape": ("Küsten des tropischen Amerika", "Ein salzverträglicher Strandbaum mit runden, ledrigen Blättern. Seine violetten Früchte hängen in traubenartigen Büscheln und ergeben ein säuerliches Gelee."),
    "black_mangrove": ("Tropische Atlantik- und Pazifikküsten Amerikas", "Eine Mangrove, deren Wurzeln bleistiftartige Atemtriebe durch den Schlamm schicken. Sie scheidet Salz über die Blätter aus, die von Kristallen glitzern."),
    "white_mangrove": ("Tropische Atlantikküsten Amerikas und Westafrikas", "Sie wächst auf der landseitigen Seite der Mangrove. Zwei kleine Drüsen am Grund jedes Blattes geben Zucker und Salz ab."),
    "buttonwood": ("Tropische Küsten Amerikas und Westafrikas", "Eine Mangrove des oberen Ufers mit knopfartigen Samenköpfen. Ihr dichtes Holz wurde in der Karibik zu Holzkohle gebrannt."),
    "nipa_palm": ("Mangroven Asiens und des Westpazifiks", "Eine stammlose Palme, deren Stamm unter dem Schlamm verläuft, nur die Wedel ragen heraus. Ihr süßer Saft wird für Zucker, Essig und Alkohol gezapft."),
    "buriti": ("Feuchtgebiete Amazoniens und des Cerrado", "Eine hohe Fächerpalme der Sümpfe und Flussufer. Ihre schuppige rote Frucht ist sehr reich an Vitamin A; aus ihrer Blattfaser flicht man Hängematten."),
    "eastern_cottonwood": ("Östliches und zentrales Nordamerika", "Eine schnellwüchsige Pappel der Flussauen mit dreieckigen Blättern. Im Frühsommer schweben ihre Samen an weißen Wattebäuschen davon."),
    "american_elm": ("Östliches Nordamerika", "Ein vasenförmiger Baum, der einst die Straßen amerikanischer Städte säumte. Das Ulmensterben, ein von Käfern verbreiteter Pilz, tötete nach 1930 die meisten."),
    "ash": ("Europa bis zum Kaukasus", "Ein hoher Baum mit gefiederten Blättern und schwarzen Winterknospen. Sein zähes, federndes Holz gab Werkzeugstiele, Ruder und Bögen; das Eschentriebsterben, ein Pilz, bedroht ihn heute."),
    "walnut": ("Zentralasien bis zum Balkan", "Die Echte Walnuss: ein breiter Baum mit duftenden Blättern und essbaren Nüssen. Ihre Wurzeln geben Juglon ab, das viele andere Pflanzen in der Nähe nicht wachsen lässt."),
    "white_mulberry": ("Nordchina", "Ein kleiner Baum, dessen Blätter die einzige Nahrung der Seidenraupe sind. Seine Staubblätter schnellen schneller auf als jede andere bekannte Pflanzenbewegung und schleudern den Pollen."),
    "linden": ("Europa und Westsibirien", "Die Winterlinde: herzförmige Blätter und duftende Blüten, die Bienen lieben. Ihr weiches weißes Holz ist bei Schnitzern beliebt, und ihr Bast gab Seile."),
    "sweet_chestnut": ("Südeuropa und Kleinasien", "Ein breiter Baum mit langen gezähnten Blättern und stacheligen Hüllen voller Kastanien. In vielen Bergdörfern waren Kastanien das Brot der Armen."),
    "pear": ("Europa und Westasien", "Der Birnbaum: weiße Frühlingsblüte und saftige Früchte, seit der Antike angebaut. Birnbaumholz ist hart und fein genug für Druckstöcke und Lineale."),
    "elder": ("Europa, Nordafrika und Westasien", "Ein strauchiger Baum mit flachen Dolden duftender cremefarbener Blüten und dunkelvioletten Beeren. Die Beeren müssen gekocht werden: Roh verderben sie den Magen."),
    "beech": ("West- und Mitteleuropa", "Ein hoher Baum mit glatter grauer Rinde und dichtem Schatten, in dem wenig anderes wächst. Seine kleinen Nüsse, die Bucheckern, mästeten im Herbst die Schweine."),
    "sugar_maple": ("Ostkanada und Nordosten der USA", "Im späten Winter steigt sein Saft mit etwa 3 % Zucker; vierzig Liter werden zu einem Liter Sirup eingekocht. Sein Blatt ist auf der Flagge Kanadas."),
    "hornbeam": ("Europa bis Iran", "Ein Baum mit gefurchtem grauem Stamm und dem härtesten Holz Europas. Man machte daraus Mühlenzahnräder, Hackklötze und Klavierhämmer."),
    "southern_magnolia": ("Südosten der USA", "Ein immergrüner Baum mit glänzenden Blättern und riesigen weißen Blüten, die nach Zitrone duften. Magnolien sind eine alte Linie, von Käfern bestäubt, bevor es Bienen gab."),
    "tulip_tree": ("Östliches Nordamerika", "Einer der höchsten Laubbäume des Ostens, mit Blättern in Tulpenumriss und grün-orangen, tulpenähnlichen Blüten."),
    "paulownia": ("Zentral- und Westchina", "Einer der am schnellsten wachsenden Bäume, mit riesigen Blättern und violetten Blüten. In Japan machte man aus seinem leichten Holz die Truhen, die Töchter zur Hochzeit bekamen."),
    "judas_tree": ("Südeuropa und Westasien", "Im Frühling brechen rosa-violette Blüten direkt aus Stamm und Ästen, noch vor den Blättern. Die Blüten sind essbar und schmecken süßsauer."),
    "quaking_aspen": ("Kanada und der Westen der USA", "Seine Blätter zittern beim leisesten Wind. Ein Espenhain in Utah, Pando, ist eine einzige Pflanze mit 47.000 Stämmen auf einem gemeinsamen Wurzelsystem."),
    "alder": ("Europa, Nordafrika und Westasien", "Ein Uferbaum, dessen Wurzeln mit Bakterien Stickstoff binden. Sein Holz hält unter Wasser: Venedig steht auf Erlenpfählen."),
    "rowan": ("Europa und Nordasien", "Ein kleiner Baum mit gefiederten Blättern und Büscheln scharlachroter Beeren, die Vögel im Herbst plündern. Sorbinsäure, ein gängiges Konservierungsmittel, wurde zuerst in ihnen gefunden."),
    "black_cherry": ("Östliches Nordamerika und Mexiko", "Eine Waldkirsche mit dunkler, schuppiger Rinde. Ihr rotbraunes Holz ist für Möbel begehrt; Blätter und Samen sind für Rinder giftig."),
    "yew": ("Europa, Nordafrika und Westasien", "Ein dunkler immergrüner Baum, der über 2.000 Jahre alt werden kann. Fast alles an ihm ist giftig; sein federndes Holz gab den englischen Langbogen, und ein Verwandter lieferte das Krebsmittel Taxol."),
    "black_walnut": ("Osten der USA", "Ein hoher Walnussbaum mit dunklem, begehrtem Holz und dickschaligen Nüssen. Die grünen Hüllen färben Hände und Stoff dunkelbraun."),
    "holly": ("West- und Südeuropa", "Ein immergrüner Baum mit stacheligen, glänzenden Blättern; nur weibliche Bäume tragen rote Beeren. Obere Blätter außer Reichweite äsender Hirsche verlieren oft ihre Stacheln."),
    "bald_cypress": ("Südosten der USA", "Ein Sumpf-Nadelbaum, der im Winter seine Nadeln abwirft. Knorrige 'Knie' ragen aus seinen Wurzeln über das Wasser; sein Holz widersteht jahrhundertelang der Fäulnis."),
    "water_tupelo": ("Südosten der USA", "Ein Sumpfbaum mit verdicktem Fuß, der monatelang im Wasser steht. Bienen machen aus seinen Blüten einen hellen Honig, der nie kristallisiert."),
    "white_willow": ("Europa und Westasien", "Eine Uferweide mit silbrigen Blättern. Ihre Rinde enthält Salicin, das natürliche Vorbild des Aspirins; eine ihrer Hybriden gibt das Holz für Cricketschläger."),
    "red_maple": ("Östliches Nordamerika", "Der häufigste Baum des östlichen Nordamerika, rot in Blüte, Stiel und Herbstlaub. Auch sein Saft wird gezapft, gibt aber weniger Zucker als der Zuckerahorn."),
    "ginkgo": ("Südwestchina", "Ein lebendes Fossil, der letzte einer Gruppe, die mit den Dinosauriern wuchs. Seine Fächerblätter werden im Herbst auf einmal golden; sechs Ginkgos überlebten die Bombe von Hiroshima."),
    "japanese_maple": ("Japan, Korea und China", "Ein kleiner Ahorn mit tief eingeschnittenen Blättern, die im Herbst rot lodern. Japanische Gärtner haben in drei Jahrhunderten Hunderte Formen gezüchtet."),
    "sugi": ("Japan", "Japans Nationalbaum, ein riesiger Nadelbaum, der um Schreine gepflanzt wird. Einige Sugi auf der Insel Yakushima sollen über 2.000 Jahre alt sein."),
    "lacquer_tree": ("China und Himalaya", "Sein Saft, Urushi, härtet an feuchter Luft zum glänzenden Lack ostasiatischer Schalen. Der rohe Saft verätzt die Haut wie sein Verwandter, der Giftsumach."),
    "cork_oak": ("Westlicher Mittelmeerraum", "Eine immergrüne Eiche mit dicker, schwammiger Rinde, die alle neun Jahre geschält wird, ohne den Baum zu töten. Portugal erzeugt die Hälfte des Korks der Welt."),
    "olive": ("Mittelmeerraum", "Ein knorriger immergrüner Baum mit silbergrauen Blättern, seit 6.000 Jahren für Öl angebaut. Olivenbäume können über tausend Jahre leben und tragen."),
    "cedar_of_lebanon": ("Gebirge des Libanon, Syriens und der Türkei", "Ein majestätischer Nadelbaum mit flachen, gestuften Ästen, auf der Flagge des Libanon. Sein duftendes, dauerhaftes Holz baute Tempel und Schiffe der Antike."),
    "black_pine": ("Südeuropa und Türkei", "Eine Kiefer mit langen, steifen, dunklen Nadeln, die Dürre, Wind und karge Böden erträgt. Man zapft sie für Harz und pflanzt sie als Windschutz."),
    "carob": ("Östlicher Mittelmeerraum", "Ein immergrüner Baum mit langen braunen Hülsen voll süßem Mark. Seine Samen sind so gleich schwer, dass sie zum Karat wurden, der Einheit für Edelsteine und Gold."),
    "stone_pine": ("Mittelmeerraum", "Die Schirmkiefer Roms mit flacher, ausladender Krone. Ihre großen Samen sind die Pinienkerne des Pesto und mediterraner Süßspeisen."),
    "aleppo_pine": ("Mittelmeerraum", "Eine dürrefeste Kiefer heißer Küsten. Der griechische Retsina-Wein wurde zuerst durch ihr Harz gewürzt, mit dem man Amphoren abdichtete."),
    "monterey_cypress": ("Zwei Haine an der Küste Mittelkaliforniens", "Wild nur in zwei Küstenhainen, aber weltweit als Windschutz gepflanzt. Meereswinde formen sie zu flachkronigen Gestalten."),
    "apple": ("Tian-Shan-Gebirge Zentralasiens", "Der Kulturapfel, Nachfahre der Wildäpfel Kasachstans. Kerne fallen nie sortenecht: Jede benannte Sorte wird von einem einzigen Urbaum veredelt."),
    "balsam_fir": ("Kanada und Nordosten der USA", "Eine duftende Tanne mit Blasen klaren Harzes in der Rinde. Kanadabalsam, das Harz, war der Kitt für Objektträger und Linsen, weil es Licht bricht wie Glas."),
    "silver_fir": ("Gebirge Mittel- und Südeuropas", "Eine hohe Tanne mit silberweißer Rinde und Nadeln mit zwei weißen Streifen unten. Sie war der erste Weihnachtsbaum des Elsass."),
    "douglas_fir": ("Westliches Nordamerika", "Einer der höchsten Bäume der Erde, mit Zapfen, deren Deckschuppen wie Mäuseschwänze aussehen. Sein festes Holz baute Brücken, Schiffsmasten und Häuser."),
    "siberian_fir": ("Sibirien und Ural", "Eine schmale Tanne der Taiga, sehr kältefest. Aus ihren Nadeln destilliertes Öl dient in Medizin und Duftseifen."),
    "green_alder": ("Gebirge und Tundra der Nordhalbkugel", "Eine buschige Erle der Lawinenbahnen und der Tundra. Sie biegt sich unter Schnee, ohne zu brechen, und bindet Stickstoff in kargen Böden."),
    "sycamore_maple": ("Gebirge Mittel- und Südeuropas", "Ein großer Ahorn mit geflügelten Samen, die sich wie Hubschrauber drehen. Sein helles Holz macht Geigenböden und Küchentische."),
    "atlas_cedar": ("Atlasgebirge in Marokko und Algerien", "Eine Bergzeder mit blaugrünen Nadelbüscheln. In ihren Wäldern leben Berberaffen, und diese Wälder schrumpfen durch Dürre und Überweidung."),
    "siberian_pine": ("Sibirien und Mongolei", "Die Sibirische 'Zeder', eine fünfnadelige Kiefer mit großen ungeflügelten Nüssen. Tannenhäher verbreiten ihre Samen, indem sie sie für den Winter vergraben."),
    "western_red_cedar": ("Pazifischer Nordwesten Nordamerikas", "Ein riesiger Nadelbaum regenreicher Küsten mit faseriger Rinde. Sein fäulnisfestes Holz gab den Küstenvölkern Kanus, Häuser und Totempfähle."),
    "sea_buckthorn": ("Europa und Asien", "Ein dorniger Strauch von Dünen und Kies mit silbrigen Blättern. Seine orangen Beeren sitzen fest an den Zweigen und sind reich an Vitamin C und Öl."),
    "european_larch": ("Alpen und Karpaten", "Ein Nadelbaum, der jeden Herbst golden wird und seine Nadeln abwirft. Sein Harz, Venezianisches Terpentin, nutzten Maler, und sein Holz widersteht Fäulnis."),
    "dahurian_larch": ("Ostsibirien und Nordostasien", "Der nördlichste Baum der Erde, auf Permafrost bei 72° Nord. Er übersteht Winter unter minus 60 °C."),
    "siberian_dwarf_pine": ("Nordostsibirien und Japan", "Eine kriechende Kiefer, die sich im Winter flach unter den Schnee legt und im Frühling wieder aufrichtet. Ihre Nüsse ernähren Bären und Zobel."),
    "eastern_white_pine": ("Ostkanada und Nordosten der USA", "Der höchste Baum des östlichen Nordamerika, mit weichen Nadeln zu fünft. Die britische Krone behielt die größten für die Masten ihrer Flotte vor."),
    "bristlecone_pine": ("White Mountains und Großes Becken, USA", "Die ältesten lebenden Bäume: Einer, Methusalem, ist über 4.800 Jahre alt. Ihre Jahresringe dienten zur Kalibrierung der Radiokarbondatierung."),
    "swiss_pine": ("Alpen und Karpaten", "Eine langsame, fünfnadelige Kiefer nahe der Baumgrenze, mit duftendem Holz für Alpenstuben. Ihre Samen verbreitet der Tannenhäher."),
    "whitebark_pine": ("Gebirge des westlichen Nordamerika", "Eine Hochgebirgskiefer, deren Zapfen sich nie von selbst öffnen; der Kiefernhäher bricht sie auf. Blasenrost und Käfer töten sie."),
    "lodgepole_pine": ("Westliches Nordamerika", "Gerade und schlank, von den Prärievölkern für Tipistangen genutzt. Viele ihrer Zapfen öffnen sich erst in der Hitze eines Waldbrands."),
    "mountain_pine": ("Gebirge Mittel- und Südeuropas", "Eine niedrige, vielstämmige Kiefer der alpinen Baumgrenze, die Schnee und Boden an steilen Hängen hält. Ihr Öl steckt in Hustenmitteln."),
    "scots_pine": ("Europa und Nordasien", "Die am weitesten verbreitete Kiefer der Welt, mit oranger Rinde oben am Stamm. Ihr Harz gab Terpentin und Teer für Taue und Rümpfe der Segelschiffe."),
    "arctic_willow": ("Arktische Tundra", "Ein Baum nur eine Hand hoch, der über die Tundra kriecht. Seine Stämmchen können Jahrhunderte alt sein; seine Blätter ernähren Moschusochsen und Hasen."),
    "coast_redwood": ("Küste Nordkaliforniens und Südoregons", "Die höchsten Bäume der Erde: Hyperion misst 116 Meter. Nebel vom Pazifik gibt ihnen im trockenen Sommer Wasser."),
    "giant_sequoia": ("Westhänge der Sierra Nevada", "Die nach Volumen größten Bäume: Der General Sherman wiegt etwa 2.000 Tonnen. Seine Rinde ist einen halben Meter dick und trotzt dem Feuer."),
    "western_hemlock": ("Pazifischer Nordwesten Nordamerikas", "Ein schattenliebender Nadelbaum mit überhängender Spitze, der unter anderen Bäumen aufwächst. Seine Rinde ist gerbstoffreich, sein Zellstoff wird zu Papier."),
    "common_juniper": ("Die ganze Nordhalbkugel", "Der am weitesten verbreitete Nadelbaum der Erde, ein Strauch der Heiden und Tundra. Seine blauen Zapfen, die Wacholderbeeren, würzen Gin."),
    "araucaria": ("Südbrasilien und Nordostargentinien", "Ein kandelaberförmiger Nadelbaum, dessen Äste oben in Büscheln enden. Seine großen Samen, Pinhão, sind im Süden Brasiliens eine Herbstspeise; der Holzeinschlag ließ nur wenige Prozent seiner Wälder übrig."),
    "brazilian_rosewood": ("Atlantischer Regenwald Brasiliens", "Rio-Palisander: dunkles, duftendes, gemasertes Kernholz, einst das feinste für Gitarren und Möbel. Seit 1992 ist sein internationaler Handel verboten."),
    "mango": ("Indien, Bangladesch und Myanmar", "Ein großer immergrüner Baum, seit 4.000 Jahren wegen seiner süßen Frucht angebaut. Saft und Schale enthalten denselben Reizstoff wie sein Verwandter, der Giftsumach."),
    "avocado": ("Mexiko und Mittelamerika", "Ein immergrüner Lorbeer, dessen Frucht reich an Öl ist, nicht an Zucker. Seinen großen Kern verbreiteten vielleicht ausgestorbene Riesenfaultiere."),
    "cashew": ("Nordostbrasilien", "Die Nuss hängt unter einem fleischigen 'Apfel', den man als Frucht oder Saft isst. Die Schale enthält ein ätzendes Öl, darum röstet man die Nüsse vor dem Öffnen."),
    "orange": ("Südchina und Südostasien (Kulturform)", "Die Süßorange, eine alte Kreuzung aus Pampelmuse und Mandarine. Brasilien erzeugt mehr Orangen als jedes andere Land."),
    "lemon": ("Nordostindien und Myanmar (Kulturform)", "Ein dorniger immergrüner Baum, dessen saure Frucht reich an Vitamin C und Zitronensäure ist. Eine Ration Zitronensaft schützte Seeleute vor Skorbut."),
    "papaya": ("Südmexiko und Mittelamerika", "Ein schneller Baum mit weichem Stamm, der schon im ersten Jahr Früchte trägt. Sein Milchsaft enthält Papain, ein Enzym, das Fleisch zerlegt."),
    "kapok": ("Tropisches Amerika und Westafrika", "Ein Riese mit Brettwurzeln, der das Kronendach des Regenwalds überragt. Seine Kapseln liefern eine leichte, wasserabweisende Faser, die einst Schwimmwesten füllte; den Maya war er heilig."),
    "sweet_cherry": ("Europa und Westasien", "Die Vogelkirsche, Stammform der süßen Gartenkirschen. Ihr rötliches Holz schätzen Tischler, und Vögel verbreiten ihre Steine."),
    "plum": ("Europa und Westasien (Kulturform)", "Die Europäische Pflaume, eine alte Kreuzung aus dem Obstgarten. Getrocknete Pflaumen sind Backpflaumen; ihre blaue Frucht trägt einen Wachsreif."),
    "peach": ("Nordwestchina (Kulturform)", "Ein kleiner Baum mit rosa Frühlingsblüte und samtigen Früchten. In China steht der Pfirsich für langes Leben."),
    "apricot": ("Zentralasien und China", "Ein früh blühender Obstbaum trockener Gebirge. Seine Kerne geben ein Öl und roh ein bitteres Gift wie Bittermandeln."),
    "fig": ("Südwestasien und Mittelmeerraum", "Ihre 'Frucht' ist ein nach innen gekehrter Blütenstand, bestäubt von einer winzigen Wespe, die hineinkriecht. Feigen gehörten zu den ersten Pflanzen, die Menschen anbauten."),
    "pomegranate": ("Iran bis Nordindien", "Ein strauchiger Baum, dessen ledrige Frucht Hunderte saftige rote Samen birgt. Ihre Schale ist reich an Gerbstoff und färbte Orientteppiche."),
    "almond": ("Südwestasien", "Ein Verwandter des Pfirsichs, angebaut wegen seines Samens. Wilde Mandeln sind bitter und giftig; ein einziges verlorenes Gen ergab die süße Mandel, die wir essen."),
    "pistachio": ("Zentralasien und Iran", "Ein Wüstenbaum, dessen reife Nüsse ihre Schale aufspringen lassen. Es gibt männliche und weibliche Bäume, daher pflanzt man einen männlichen auf acht weibliche."),
    "hazel": ("Europa und Westasien", "Ein vielstämmiger, strauchiger Baum mit Kätzchen im späten Winter. Aus seinen geraden Ruten flocht man Zäune, und man schnitt daraus Wünschelruten."),
    "pecan": ("Mississippital und Mexiko", "Ein hoher Hickory der Flussauen mit süßen, dünnschaligen Nüssen. Er war Nahrung der amerikanischen Ureinwohner, lange bevor er zur Kulturpflanze wurde."),
    "plane_tree": ("Südosteuropa bis Iran", "Ein breiter Schattenbaum, dessen Rinde in Flecken abblättert. Hippokrates soll auf der Insel Kos unter einer gelehrt haben."),
    "horse_chestnut": ("Gebirge des Balkans", "Ein breiter Baum mit Kerzen weißer Blüten und glänzend braunen Kastanien. Seine Samen sind trotz des Namens für Menschen giftig."),
}

